# Build the FP32 Spike pieces WITHOUT touching ~/chipyard: a private include dir (stock headers + the FP32 gemmini_params.h
# generated by logs/m7a-genparams.py) for the test, and a private libgemmini .so compiled against that params header.
source ~/miniforge3/etc/profile.d/conda.sh; cd ~/chipyard; source env.sh
R=/mnt/c/Users/braed/gemmini-nvfp4; W=~/nvfp4-logs/m7a
RT=~/chipyard/generators/gemmini/software/gemmini-rocc-tests; LG=~/chipyard/generators/gemmini/software/libgemmini
rm -rf $W/fp32inc $W/libgemmini-fp32; mkdir -p $W/fp32inc/include $W/libgemmini-fp32
cp $RT/include/*.h $W/fp32inc/include/
cp $R/logs/m7a-gemmini_params_fp32.h $W/fp32inc/include/gemmini_params.h
cp $LG/gemmini.cc $LG/gemmini.h $W/libgemmini-fp32/
cp $R/logs/m7a-gemmini_params_fp32.h $W/libgemmini-fp32/gemmini_params.h
cd $W/libgemmini-fp32
echo "libgemmini build: g++ -L \$RISCV/lib -Wl,-rpath,\$RISCV/lib -shared -o libgemmini_fp32.so -std=c++17 -I \$RISCV/include -fPIC -O3 gemmini.cc"
g++ -L $RISCV/lib -Wl,-rpath,$RISCV/lib -shared -o libgemmini_fp32.so -std=c++17 -I $RISCV/include -fPIC -O3 gemmini.cc 2>&1 | head -20
ls -la libgemmini_fp32.so
bash $R/logs/m7a-build.sh fp32 m7a_fp32
